import collections
DELTA=800
def closures(evs, delta=DELTA):
    # first-time of each undirected pair
    first={}
    for u,v,t in evs:
        k=(min(u,v),max(u,v))
        if k not in first: first[k]=t
    adj=collections.defaultdict(list)  # node -> list (nbr, t)
    for (a,b),t in first.items():
        adj[a].append((b,t)); adj[b].append((a,t))
    res=[]
    for (a,b),tc in first.items():
        # find common contacts c with edges (a,c),(b,c) both before tc
        na={x:tt for x,tt in adj[a] if tt<tc}
        for x,tt in adj[b]:
            if tt<tc and x in na:
                support=max(tt,na[x])
                if tc-support<=delta:
                    res.append((a,b,x,tc,support,tc-support))
    return first,res

